#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for(int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y) {
        assert(x > 0 && y > 0 && x + y < n);
        ops.push_back({x, y});
        vector<int> np;
        for(int i = n-y; i < n; i++) np.push_back(p[i]);
        for(int i = x; i < n-y; i++) np.push_back(p[i]);
        for(int i = 0; i < x; i++) np.push_back(p[i]);
        p = np;
    };

    for(int target = 0; target < n - 2; target++){
        int pos = -1;
        for(int i = target; i < n; i++) if(p[i] == target + 1){ pos = i; break; }
        if(pos == target) continue;

        int remaining = n - target; // elements from target..n-1 that we're working with
        // But operations are on the full array. Elements [0..target-1] are already sorted.

        // Step 1: bring element to position n-1
        if(pos != n-1){
            if(pos == n-2){
                // x = n-2, y = 1: suffix=[p[n-1]], middle=empty? No, x+y=n-1<n, middle=[p[n-2..n-2]]. Wait middle is p[x..n-y-1]=p[n-2..n-2]. So new=[p[n-1],p[n-2],p[0..n-3]]. Element at pos n-2 goes to position 1. That's not n-1.
                // x=1, y=1: new=[p[n-1],p[1..n-2],p[0]]. Element at n-2 stays at n-2. Not helpful.
                // x=pos-target+1 (only move unsorted part). Hmm, let's just use: move to pos 0 first.
                // y=n-pos: element at pos becomes first in suffix → position 0. Need x < pos and x>=1.
                int y = n - pos; // = 2
                int x = max(1, target > 0 ? target : 1);
                if(x + y < n) apply(x, y);
                pos = 0;
            }
            if(pos != n-1 && pos >= 2){
                int y = n - pos;
                int x = 1;
                if(x + y < n) apply(x, y);
                pos = 0;
            }
            if(pos == 0){ apply(1, max(1, n-2 > 0 ? n-2 : 1)); pos = n-1; }
            else if(pos == 1){ apply(1, 1); pos = n-1; } // goes to position... let me just recompute
            // Fallback: find position again
            for(int i = 0; i < n; i++) if(p[i]==target+1){ pos=i; break; }
        }
        if(pos == n-1 && target < n-1){
            int y = n - 1 - target;
            int x = max(1, target);
            if(x > 0 && y > 0 && x+y < n) apply(x, y);
        }
    }

    printf("%d\n", (int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n", x, y);
}
